export function preventiveStep(s,{log},access){const med=s.clinical;med.preventive??={records:[],next:Math.max(56,s.day),complete:false};const p=med.preventive;if(!access.available||s.medical.episode||med.active||s.day<p.next)return;const first=!p.records.length;const juvenile=s.day<140;log(s,first?'preventive-visit':juvenile?'preventive-followup':'health-check',first?'진료실에서 성장 상태와 이전 접종 기록을 확인한다. 수의사가 나이와 생활환경에 맞춰 필요한 예방 관리를 정한다.':juvenile?'돌보는 사람이 지난번 기록을 가지고 병원에 왔다. 몸 상태를 확인한 뒤 예정된 예방 관리를 이어간다.':'정기 검진에서 체중과 입 안, 귀와 걸음을 살핀다. 이전 질환과 먹이·활동의 변화도 함께 확인한다.');p.records.push({day:s.day,kind:first?'assessment':juvenile?'followup':'check',human:s.caregiverId});p.complete=p.records.length>=3||!juvenile;p.next=s.day+(juvenile?28:330);med.preventionDone=true;med.nextCheck=p.next;return true;}
